import{_ as s,o as e,c as n,a3 as t}from"./chunks/framework.goqT_hzs.js";const g=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"developers/examples.md","filePath":"developers/examples.md"}'),p={name:"developers/examples.md"};function i(o,a,l,r,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>Each block runs as written in one <code>s32 --loopback repl</code>. On an S32, start <code>s32 --usb repl</code> instead.</p><h2 id="back-up-and-restore-a-project" tabindex="-1">Back up and restore a project <a class="header-anchor" href="#back-up-and-restore-a-project" aria-label="Permalink to &quot;Back up and restore a project&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; list</span></span>
<span class="line"><span>s32&gt; pull internal 1 /tmp/p1.s32p</span></span>
<span class="line"><span>s32&gt; push /tmp/p1.s32p</span></span>
<span class="line"><span>s32&gt; push /tmp/p1.s32p --activate</span></span>
<span class="line"><span>s32&gt; active</span></span></code></pre></div><p>See <a href="./commands/projects#push">Push</a>.</p><h2 id="map-a-knob-to-filter-cutoff" tabindex="-1">Map a knob to filter cutoff <a class="header-anchor" href="#map-a-knob-to-filter-cutoff" aria-label="Permalink to &quot;Map a knob to filter cutoff&quot;">​</a></h2><p>Knob 05, macro 2, CC 74 on channel 3:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; macro set 4 1 mode=cc msb=74 channel=3</span></span>
<span class="line"><span>s32&gt; potname set 4 Cutoff</span></span>
<span class="line"><span>s32&gt; macro get 4 1</span></span></code></pre></div><p>See <a href="./commands/macros">Macros</a> for every mode.</p><h2 id="add-an-arpeggiator" tabindex="-1">Add an Arpeggiator <a class="header-anchor" href="#add-an-arpeggiator" aria-label="Permalink to &quot;Add an Arpeggiator&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; device add 0 arp</span></span>
<span class="line"><span>s32&gt; device list 0</span></span>
<span class="line"><span>s32&gt; device param set 0 1 rate 6</span></span>
<span class="line"><span>s32&gt; device param get 0 1 rate</span></span></code></pre></div><h2 id="sweep-the-arpeggiator-gate-with-an-lfo" tabindex="-1">Sweep the Arpeggiator gate with an LFO <a class="header-anchor" href="#sweep-the-arpeggiator-gate-with-an-lfo" aria-label="Permalink to &quot;Sweep the Arpeggiator gate with an LFO&quot;">​</a></h2><p>Continue from the block above. <code>rack=</code> and <code>device=</code> are <a href="./commands/racks">ids, not positions</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; lfo cfg set s32 0 wave=triangle freq=0.5 enabled=on</span></span>
<span class="line"><span>s32&gt; lfo assign add 0 target=device rack=100 device=1 param=gate min=20 max=80</span></span>
<span class="line"><span>s32&gt; lfo assign add 0 target=lfo targetLfo=1 param=amplitude min=0 max=1</span></span>
<span class="line"><span>s32&gt; lfo assign add 0 target=macro pot=2 macro=1</span></span>
<span class="line"><span>s32&gt; lfo assign list</span></span></code></pre></div><p>LFO 1 now also moves LFO 2&#39;s amplitude and knob 03, macro 2.</p><h2 id="grab-the-screen" tabindex="-1">Grab the screen <a class="header-anchor" href="#grab-the-screen" aria-label="Permalink to &quot;Grab the screen&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; view nav s32-lfo index=2</span></span>
<span class="line"><span>s32&gt; screen png /tmp/oled.png</span></span></code></pre></div><h2 id="watch-the-knobs" tabindex="-1">Watch the knobs <a class="header-anchor" href="#watch-the-knobs" aria-label="Permalink to &quot;Watch the knobs&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Prints knob events for eight seconds.</p><h2 id="build-a-song-in-arrange" tabindex="-1">Build a song in Arrange <a class="header-anchor" href="#build-a-song-in-arrange" aria-label="Permalink to &quot;Build a song in Arrange&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot store knobs next Verse</span></span>
<span class="line"><span>s32&gt; snapshot store knobs next Chorus</span></span>
<span class="line"><span>s32&gt; snapshot arrange set repeat=loop rate=4 length=16 knobs=0,1,0,1</span></span>
<span class="line"><span>s32&gt; snapshot arrange get</span></span></code></pre></div><p>New projects start with <strong>ARRANGE</strong> off, and USB writes the song but not that switch. Turn <strong>ARRANGE</strong> on in the pencil tab on the panel to start the playhead.</p><p>See <a href="./commands/snapshots#arrange">Arrange</a>.</p>`,24)])])}const b=s(p,[["render",i]]);export{g as __pageData,b as default};
